/* DWARF original prototype: bool DelQuickslot(CHARACTER * this, BYTE pos) */

bool __thiscall CHARACTER::DelQuickslot(CHARACTER *this,BYTE pos)

{
  packet_quickslot_del pack_quickslot_del;
  
  if (pos < 0x24) {
    this->m_quickslot[pos].type = '\0';
    this->m_quickslot[pos].pos = '\0';
    pack_quickslot_del.pos = pos;
    pack_quickslot_del.header = '\x1d';
    DESC::Packet((this->super_CEntity).m_lpDesc,&pack_quickslot_del,2);
  }
  return pos < 0x24;
}
